/* 小晏川表情系统 v1：原网页外接脚本，保留原本动作 */
(()=>{'use strict';
const pet=document.getElementById('pet'),box=document.getElementById('petbox'),bubble=document.getElementById('bubble');
if(!pet||!box)return;
const original=pet.src,half='data:image/png;base64,',closed='data:image/png;base64,';
const happy='yc-happy-final.gif';
let timer=null,lock=0;
function set(src){pet.src=src;}
function reset(){clearTimeout(timer);set(original);lock=0;}
function showHappy(){
  clearTimeout(timer);lock=Date.now()+2400;
  set(happy+'?play='+Date.now());
  timer=setTimeout(reset,2400);
}
function blink(){
  if(document.hidden||Date.now()<lock||pet.classList.contains('sleep'))return;
  set(half);setTimeout(()=>{if(Date.now()<lock)return;set(closed);setTimeout(()=>{if(Date.now()<lock)return;set(half);setTimeout(()=>{if(Date.now()>=lock)set(original)},100)},95)},95);
}
function schedule(){setTimeout(()=>{blink();schedule()},3500+Math.random()*4500)}
schedule();
// 原有情绪模块使用 click；捕获阶段只补充图片，不阻断原处理。
box.addEventListener('click',e=>{
 const y=(e.clientY-box.getBoundingClientRect().top)/box.getBoundingClientRect().height;
 if(y<.47)showHappy();
},true);
document.getElementById('hug')?.addEventListener('click',showHappy);
document.getElementById('sleep')?.addEventListener('click',()=>{
 clearTimeout(timer);lock=Date.now()+5200;set(closed);
 timer=setTimeout(reset,5200);
});
document.getElementById('walk')?.addEventListener('click',reset);
})();
